MultiplayerColorDefinition *MultiplayerSettings::findMultiplayerColorDefinitionByName(AsciiString name)
{
	for (MultiplayerColorList::iterator entry = m_colorList.begin(); entry != m_colorList.end(); ++entry)
	{
		if (entry->second.getTooltipName() == name)
			return &entry->second;
	}
	return NULL;
}

